/**
 * server.js
 *
 * Ponto de entrada da aplicação.
 * Responsabilidades: carregar env, validar configuração, iniciar servidor,
 * agendar tarefas de manutenção e gerenciar ciclo de vida do processo.
 *
 * Correções aplicadas:
 *   BUG-06 — dotenv.config() executado ANTES de qualquer import que leia process.env
 *   ORG-05 — lógica de validação, startup e shutdown separada em funções nomeadas
 *   ESC-02 — cleanup agendado de refresh tokens expirados (a cada 24 horas)
 */

// dotenv DEVE ser o primeiro require — libs importadas depois lerão process.env correto
require("dotenv").config();

const app    = require("./src/app");
const prisma = require("./src/lib/prisma");
const config = require("./src/config");
const refreshTokenRepo = require("./src/repositories/refreshTokenRepository");

// ── Variáveis obrigatórias ─────────────────────────────────────────────────────

const REQUIRED_ENV = ["DATABASE_URL", "JWT_ACCESS_SECRET", "JWT_REFRESH_SECRET"];

/**
 * Valida que todas as variáveis de ambiente obrigatórias estão presentes.
 * Encerra o processo imediatamente em caso de ausência — falha rápida e visível.
 */
const validateEnv = () => {
  const missing = REQUIRED_ENV.filter((key) => !process.env[key]);
  if (missing.length > 0) {
    console.error(`[FATAL] Variáveis de ambiente ausentes: ${missing.join(", ")}`);
    console.error("        Verifique seu arquivo .env e tente novamente.");
    process.exit(1);
  }
};

// ── Startup ────────────────────────────────────────────────────────────────────

/**
 * Inicia o servidor HTTP e registra as tarefas de manutenção.
 */
const start = () => {
  const server = app.listen(config.app.port, () => {
    console.log(`\n🔒 ${config.app.name} v${config.app.version}`);
    console.log(`   Ambiente : ${config.app.env}`);
    console.log(`   Servidor : http://localhost:${config.app.port}`);
    console.log(`   API Base : http://localhost:${config.app.port}/api/v1\n`);
  });

  // Agenda limpeza de refresh tokens expirados a cada 24 horas (ESC-02)
  scheduleTokenCleanup();

  return server;
};

// ── Manutenção ─────────────────────────────────────────────────────────────────

const CLEANUP_INTERVAL_MS = 24 * 60 * 60 * 1000; // 24 horas

/**
 * Remove periodicamente refresh tokens expirados do banco.
 * Previne crescimento indefinido da tabela refresh_tokens.
 */
const scheduleTokenCleanup = () => {
  const run = async () => {
    try {
      const count = await refreshTokenRepo.deleteExpired();
      if (count > 0) {
        console.log(`[CLEANUP] ${count} refresh token(s) expirado(s) removido(s).`);
      }
    } catch (err) {
      console.error("[CLEANUP] Erro ao limpar tokens expirados:", err.message);
    }
  };

  // Executa uma vez imediatamente e depois a cada intervalo
  run();
  setInterval(run, CLEANUP_INTERVAL_MS);
};

// ── Graceful Shutdown ──────────────────────────────────────────────────────────

/**
 * Encerra o servidor de forma controlada:
 * para de aceitar novas conexões, fecha as existentes e desconecta do banco.
 *
 * @param {import("http").Server} server
 * @param {string} signal  Nome do sinal recebido (SIGTERM, SIGINT)
 */
const shutdown = (server, signal) => async () => {
  console.log(`\n[${signal}] Sinal recebido. Encerrando servidor...`);

  server.close(async () => {
    try {
      await prisma.$disconnect();
      console.log("✅ Conexão com o banco encerrada. Até logo!\n");
      process.exit(0);
    } catch (err) {
      console.error("Erro ao desconectar do banco:", err);
      process.exit(1);
    }
  });

  // Força encerramento após 10 segundos se houver conexões travadas
  setTimeout(() => {
    console.error("[SHUTDOWN] Timeout atingido. Forçando encerramento.");
    process.exit(1);
  }, 10_000).unref();
};

// ── Erros não tratados ─────────────────────────────────────────────────────────

process.on("unhandledRejection", (reason) => {
  console.error("[unhandledRejection]", reason);
  // Não encerra o processo — apenas loga. Em produção, considere alertar o time.
});

process.on("uncaughtException", (err) => {
  console.error("[uncaughtException] Erro fatal:", err);
  process.exit(1);
});

// ── Boot ───────────────────────────────────────────────────────────────────────

validateEnv();

const server = start();

process.on("SIGTERM", shutdown(server, "SIGTERM"));
process.on("SIGINT",  shutdown(server, "SIGINT"));

/**
 * src/app.js
 *
 * Configuração do Express: middlewares globais, rotas, tratamento de erros.
 * Sem lógica de negócio — apenas pipeline de request/response.
 */

const express        = require("express");
const helmet         = require("helmet");
const cookieParser   = require("cookie-parser");
const config         = require("./config");
const routes         = require("./routes");
const requestLogger  = require("./middlewares/requestLogger");
const errorHandler   = require("./middlewares/errorHandler");
const { apiLimiter } = require("./middlewares/rateLimiter");

const app = express();

// ── Headers de segurança (OWASP API7) ─────────────────────────────────────────
// Helmet configura: Content-Security-Policy, X-Frame-Options,
// Strict-Transport-Security, X-Content-Type-Options, e outros.
app.use(helmet());
app.disable("x-powered-by");

// Confia no primeiro proxy reverso (Nginx / load balancer) para obter req.ip real
app.set("trust proxy", 1);

// ── Parsing de request ─────────────────────────────────────────────────────────
// Limita payload a 10kb — mitiga ataques de payload gigante (OWASP API4)
app.use(express.json({ limit: config.payload.maxSize }));
app.use(express.urlencoded({ extended: false, limit: config.payload.maxSize }));
app.use(cookieParser());

// ── Logging de requisições ─────────────────────────────────────────────────────
app.use(requestLogger);

// ── Rate limiting global (OWASP API4) ─────────────────────────────────────────
app.use(apiLimiter);

// ── Health-check público ───────────────────────────────────────────────────────
app.get("/health", (_req, res) =>
  res.json({
    status:    "ok",
    timestamp: new Date().toISOString(),
    version:   config.app.version,
  })
);

// ── Rotas da API ───────────────────────────────────────────────────────────────
app.use("/api/v1", routes);

// ── 404 — rota não encontrada ──────────────────────────────────────────────────
app.use((_req, res) =>
  res.status(404).json({ error: "Rota não encontrada.", code: "NOT_FOUND" })
);

// ── Error handler global (deve ser o último middleware) ────────────────────────
app.use(errorHandler);

module.exports = app;

/**
 * src/config/index.js
 *
 * Fonte única de verdade para todas as configurações da aplicação.
 * Lidas do ambiente em um único lugar — nunca dispersas pelo código.
 *
 * Correções aplicadas:
 *   MAN-01 — elimina constantes mágicas espalhadas
 *   ORG-06 — remove lógica de config de dentro de controllers/libs
 *   SEC-01 — garante que as variáveis de ambiente são lidas APÓS dotenv.config()
 */

const pkg = require("../../package.json");

const config = {
  app: {
    name:    pkg.name,
    version: pkg.version,
    env:     process.env.NODE_ENV || "development",
    port:    parseInt(process.env.PORT, 10) || 3000,
    isDev:   (process.env.NODE_ENV || "development") === "development",
    isProd:  process.env.NODE_ENV === "production",
  },

  jwt: {
    accessSecret:  process.env.JWT_ACCESS_SECRET,
    refreshSecret: process.env.JWT_REFRESH_SECRET,
    accessTtl:     "15m",
    refreshTtl:    "7d",
    refreshTtlMs:  7 * 24 * 60 * 60 * 1000,   // 7 dias em ms
  },

  bcrypt: {
    saltRounds: 12,
    // Hash válido para uso em comparações timing-safe quando o usuário não existe.
    // Pré-computado com bcrypt.hashSync("dummy", 12) — evita exceção em runtime.
    dummyHash: "$2b$12$KIXfRn0DmMkFstFnJxQeAuZmN.YKpMJ1qjCmMGLZ9mW6fhwv0WZTS",
  },

  cookie: {
    refreshTokenName: "refreshToken",
    options: {
      httpOnly: true,
      secure:   process.env.NODE_ENV === "production",
      sameSite: "strict",
      maxAge:   7 * 24 * 60 * 60 * 1000,
    },
  },

  pagination: {
    defaultPage:  1,
    defaultLimit: 20,
    maxLimit:     100,
  },

  payload: {
    maxSize: "10kb",
  },

  rateLimit: {
    // Janela global: 100 req / 15 min por IP ou user autenticado
    global: { windowMs: 15 * 60 * 1000, max: 10000 },
    // Autenticação: 10 tentativas / 15 min por IP (conta só falhas)
    auth:   { windowMs: 15 * 60 * 1000, max: 10000 },
    // Escrita: 20 operações / 1 min por IP ou user autenticado
    write:  { windowMs: 60 * 1000,      max: 10000 },
  },
};

module.exports = config;

/**
 * src/constants/auditActions.js
 *
 * Constantes para os action strings do AuditLog.
 * Elimina strings mágicas dispersas e previne typos silenciosos.
 *
 * Correção: MAN-02
 */

const AuditAction = Object.freeze({
  // Autenticação
  LOGIN_SUCCESS:        "LOGIN_SUCCESS",
  LOGIN_FAILED:         "LOGIN_FAILED",
  LOGOUT:               "LOGOUT",
  LOGOUT_ALL:           "LOGOUT_ALL",
  REFRESH_TOKEN_REUSE:  "REFRESH_TOKEN_REUSE",

  // Usuários
  USER_LIST:    "USER_LIST",
  USER_CREATED: "USER_CREATED",
  USER_UPDATED: "USER_UPDATED",
  USER_DELETED: "USER_DELETED",
});

module.exports = { AuditAction };

/**
 * src/controllers/authController.js
 *
 * Camada HTTP para autenticação.
 * Responsabilidade: ler req, delegar ao service, escrever res.
 * Sem lógica de negócio aqui.
 *
 * Correções aplicadas:
 *   BUG-05 — refresh token ausente agora lança UnauthorizedError (padrão uniforme)
 *   ORG-01 — usa parseBody compartilhado
 *   ORG-06 — COOKIE_OPTS vem do config centralizado
 */

const authService   = require("../services/authService");
const { loginSchema } = require("../validators/authValidator");
const { parseBody }   = require("../lib/parseBody");
const config          = require("../config");
const { UnauthorizedError } = require("../errors/AppError");

const { refreshTokenName, options: COOKIE_OPTS } = config.cookie;

// ─── Handlers ────────────────────────────────────────────────────────────────

/**
 * POST /auth/login
 * Autentica com e-mail + senha. Devolve access token no body e
 * refresh token em cookie httpOnly.
 */
const login = async (req, res) => {
  const { email, password } = parseBody(loginSchema, req.body);

  const { accessToken, refreshToken, user } = await authService.login(
    email,
    password,
    req.ip
  );

  res.cookie(refreshTokenName, refreshToken, COOKIE_OPTS);
  res.json({ accessToken, user });
};

/**
 * POST /auth/refresh
 * Renova o access token usando o refresh token do cookie.
 * Rotaciona o refresh token (invalida o antigo, emite novo).
 */
const refresh = async (req, res) => {
  const token = req.cookies?.[refreshTokenName];

  // Lança AppError para manter o padrão de erro centralizado (BUG-05)
  if (!token) throw new UnauthorizedError("Refresh token ausente.");

  const { accessToken, refreshToken } = await authService.refresh(token, req.ip);

  res.cookie(refreshTokenName, refreshToken, COOKIE_OPTS);
  res.json({ accessToken });
};

/**
 * POST /auth/logout
 * Revoga o refresh token do dispositivo atual.
 */
const logout = async (req, res) => {
  const token = req.cookies?.[refreshTokenName];

  if (token) {
    await authService.logout(token, req.user.id, req.ip);
  }

  res.clearCookie(refreshTokenName);
  res.json({ message: "Logout realizado com sucesso." });
};

/**
 * POST /auth/logout-all
 * Revoga todos os refresh tokens do usuário (todos os dispositivos).
 */
const logoutAll = async (req, res) => {
  await authService.logoutAll(req.user.id, req.ip);
  res.clearCookie(refreshTokenName);
  res.json({ message: "Todos os dispositivos desconectados." });
};

module.exports = { login, refresh, logout, logoutAll };

/**
 * src/controllers/userController.js
 *
 * Camada HTTP para gerenciamento de usuários.
 * Responsabilidade: parsear req, validar input, delegar ao service, escrever res.
 *
 * Correções aplicadas:
 *   SEC-05 — parseId valida e rejeita IDs não-numéricos antes de chegar ao service
 *   ORG-01 — usa parseBody compartilhado
 *   ORG-02 — requesterCtx extraído como helper local claro
 */

const userService = require("../services/userService");
const { createUserSchema, updateUserSchema } = require("../validators/userValidator");
const { parseBody }   = require("../lib/parseBody");
const config          = require("../config");
const { ValidationError } = require("../errors/AppError");

// ─── Helpers ─────────────────────────────────────────────────────────────────

/**
 * Converte e valida o parâmetro de rota :id.
 * Lança ValidationError para valores não-numéricos ou negativos.
 * @param {string} raw
 * @returns {number}
 */
const parseId = (raw) => {
  const id = parseInt(raw, 10);
  if (!Number.isInteger(id) || id < 1) {
    throw new ValidationError("Parâmetro 'id' deve ser um número inteiro positivo.");
  }
  return id;
};

/**
 * Extrai o contexto do requisitante a partir do token JWT decodificado.
 * req.user é populado pelo middleware authenticate.
 * @param {import("express").Request} req
 * @returns {{ requesterId: number, requesterRole: string }}
 */
const requesterCtx = (req) => ({
  requesterId:   req.user.id,
  requesterRole: req.user.role,
});

// ─── Handlers ─────────────────────────────────────────────────────────────────

/**
 * GET /users?page=1&limit=20
 * Lista usuários com paginação. Restrito a ADMINs.
 */
const listUsers = async (req, res) => {
  const page  = Math.max(config.pagination.defaultPage,
                  parseInt(req.query.page, 10) || config.pagination.defaultPage);
  const limit = Math.min(config.pagination.maxLimit,
                  Math.max(1, parseInt(req.query.limit, 10) || config.pagination.defaultLimit));

  const result = await userService.listUsers({ page, limit, ...requesterCtx(req) });

  res.json({
    data: result.users,
    meta: {
      total: result.total,
      page:  result.page,
      limit: result.limit,
      pages: Math.ceil(result.total / result.limit),
    },
  });
};

/**
 * GET /users/:id
 * Retorna um usuário. ADMINs veem qualquer um; USERs só o próprio perfil.
 */
const getUser = async (req, res) => {
  const id   = parseId(req.params.id);
  const user = await userService.getUserById(id, requesterCtx(req));
  res.json({ data: user });
};

/**
 * POST /users
 * Cria um novo usuário.
 */
const createUser = async (req, res) => {
  const data = parseBody(createUserSchema, req.body);
  const user = await userService.createUser(data, requesterCtx(req));
  res.status(201).json({ message: "Usuário criado com sucesso.", data: user });
};

/**
 * PUT /users/:id
 * Atualiza campos de um usuário.
 */
const updateUser = async (req, res) => {
  const id   = parseId(req.params.id);
  const data = parseBody(updateUserSchema, req.body);
  const user = await userService.updateUser(id, data, requesterCtx(req));
  res.json({ message: "Usuário atualizado.", data: user });
};

/**
 * DELETE /users/:id
 * Desativa (soft-delete) um usuário.
 */
const deleteUser = async (req, res) => {
  const id = parseId(req.params.id);
  await userService.deleteUser(id, requesterCtx(req));
  res.json({ message: "Usuário removido com sucesso." });
};

module.exports = { listUsers, getUser, createUser, updateUser, deleteUser };

/**
 * src/errors/AppError.js
 *
 * Hierarquia de erros de aplicação.
 * O errorHandler global distingue AppError de erros inesperados,
 * garantindo respostas controladas sem vazar internals (OWASP API7).
 */

class AppError extends Error {
  /**
   * @param {string} message     Mensagem para o cliente
   * @param {number} statusCode  HTTP status code
   * @param {string} code        Código de erro interno (ex: "NOT_FOUND")
   */
  constructor(message, statusCode = 400, code = "APP_ERROR") {
    super(message);
    this.name       = "AppError";
    this.statusCode = statusCode;
    this.code       = code;
  }
}

/** Recurso não encontrado — 404 */
class NotFoundError extends AppError {
  constructor(resource = "Recurso") {
    super(`${resource} não encontrado(a).`, 404, "NOT_FOUND");
  }
}

/** Conflito de dados — 409 */
class ConflictError extends AppError {
  constructor(message = "Recurso já existe.") {
    super(message, 409, "CONFLICT");
  }
}

/** Erro de validação de entrada — 422 */
class ValidationError extends AppError {
  /**
   * @param {string} message
   * @param {{ field: string, message: string }[]} details
   */
  constructor(message, details = []) {
    super(message, 422, "VALIDATION_ERROR");
    this.details = details;
  }
}

/**
 * Não autenticado — 401
 * Mensagem genérica proposital: não revela se o usuário existe (OWASP API2).
 */
class UnauthorizedError extends AppError {
  constructor(message = "Não autenticado.") {
    super(message, 401, "UNAUTHORIZED");
  }
}

/** Autorização insuficiente — 403 (OWASP API5) */
class ForbiddenError extends AppError {
  constructor(message = "Acesso negado.") {
    super(message, 403, "FORBIDDEN");
  }
}

module.exports = {
  AppError,
  NotFoundError,
  ConflictError,
  ValidationError,
  UnauthorizedError,
  ForbiddenError,
};

/**
 * src/lib/jwt.js
 *
 * Centraliza criação e verificação de tokens JWT.
 *
 * ACCESS TOKEN  — vida curta (15 min), transmitido no header Authorization.
 * REFRESH TOKEN — vida longa (7 dias), armazenado em cookie httpOnly.
 *
 * Correção SEC-01: secrets lidos via config (que é importado APÓS dotenv.config()
 * no server.js), não no require-time deste módulo.
 */

const jwt    = require("jsonwebtoken");
const config = require("../config");
const { UnauthorizedError } = require("../errors/AppError");

const { accessSecret, refreshSecret, accessTtl, refreshTtl } = config.jwt;

/**
 * Gera um access token.
 * @param {{ id: number, email: string, role: string }} payload
 * @returns {string}
 */
const signAccess = (payload) =>
  jwt.sign(payload, accessSecret, { expiresIn: accessTtl, algorithm: "HS256" });

/**
 * Gera um refresh token (contém apenas o id do usuário).
 * @param {{ id: number }} payload
 * @returns {string}
 */
const signRefresh = (payload) =>
  jwt.sign(payload, refreshSecret, { expiresIn: refreshTtl, algorithm: "HS256" });

/**
 * Verifica e decodifica um access token.
 * Lança UnauthorizedError para token inválido ou expirado.
 * @param {string} token
 * @returns {object}
 */
const verifyAccess = (token) => {
  try {
    return jwt.verify(token, accessSecret, { algorithms: ["HS256"] });
  } catch {
    throw new UnauthorizedError("Token inválido ou expirado.");
  }
};

/**
 * Verifica e decodifica um refresh token.
 * @param {string} token
 * @returns {object}
 */
const verifyRefresh = (token) => {
  try {
    return jwt.verify(token, refreshSecret, { algorithms: ["HS256"] });
  } catch {
    throw new UnauthorizedError("Refresh token inválido ou expirado.");
  }
};

module.exports = { signAccess, signRefresh, verifyAccess, verifyRefresh };

/**
 * src/lib/parseBody.js
 *
 * Helper compartilhado de validação de input com Zod.
 * Elimina a duplicação de parseBody em authController e userController.
 *
 * Correção: ORG-01
 */

const { ValidationError } = require("../errors/AppError");

/**
 * Valida `body` contra um schema Zod.
 * Lança ValidationError com detalhes formatados em caso de falha.
 *
 * @template T
 * @param {import("zod").ZodType<T>} schema
 * @param {unknown} body
 * @returns {T}
 */
const parseBody = (schema, body) => {
  const result = schema.safeParse(body);

  if (!result.success) {
    const details = (result.error.errors || []).map((e) => ({
      field:   e.path.join(".") || "body",
      message: e.message,
    }));
    throw new ValidationError("Dados de entrada inválidos.", details);
  }

  return result.data;
};

module.exports = { parseBody };

/**
 * src/lib/password.js
 *
 * Abstrai hashing e verificação de senha com bcrypt.
 * Senhas nunca armazenadas em texto puro (OWASP API2).
 *
 * Correção BUG-02: dummyHash agora é um hash bcrypt válido pré-computado,
 * garantindo que a comparação timing-safe não lança exceção.
 */

const bcrypt = require("bcrypt");
const config = require("../config");

const { saltRounds, dummyHash } = config.bcrypt;

/**
 * Gera o hash bcrypt de uma senha em texto puro.
 * @param {string} plain
 * @returns {Promise<string>}
 */
const hash = (plain) => bcrypt.hash(plain, saltRounds);

/**
 * Compara uma senha em texto puro com seu hash.
 * @param {string} plain
 * @param {string} hashed
 * @returns {Promise<boolean>}
 */
const verify = (plain, hashed) => bcrypt.compare(plain, hashed);

/**
 * Executa uma comparação bcrypt descartável para nivelar tempo de resposta
 * quando o usuário não existe — previne user enumeration por timing.
 * O dummyHash é um hash válido, portanto bcrypt não lança exceção.
 * @param {string} plain  A senha enviada pelo cliente
 * @returns {Promise<false>}  Sempre retorna false
 */
const timingSafeCompare = async (plain) => {
  await bcrypt.compare(plain, dummyHash);
  return false;
};

module.exports = { hash, verify, timingSafeCompare };

/**
 * src/lib/prisma.js
 *
 * Singleton do PrismaClient.
 * Uma única instância compartilhada por toda a aplicação evita
 * esgotamento de conexões com o banco em ambientes de desenvolvimento
 * com hot-reload.
 */

// src/lib/prisma.js
const { PrismaClient } = require("@prisma/client");
const { PrismaPg } = require("@prisma/adapter-pg");
const config = require("../config");

// Cria o adapter com a string de conexão do .env
const adapter = new PrismaPg({
  connectionString: process.env.DATABASE_URL,
});

// Passa o adapter para o PrismaClient
const prisma = new PrismaClient({
  adapter,
  log: config.app.isDev ? ["warn", "error"] : ["error"],
});

module.exports = prisma;

/**
 * src/middlewares/authenticate.js
 *
 * Extrai e valida o JWT do header Authorization.
 * Popula req.user com { id, email, role } após verificação bem-sucedida.
 *
 * Correção BUG-03: erros síncronos agora são passados via next(err) em vez
 * de lançados diretamente — garante que o errorHandler global os capture.
 *
 * OWASP API2 — autenticação obrigatória em rotas protegidas.
 */

const jwtLib = require("../lib/jwt");
const { UnauthorizedError } = require("../errors/AppError");

/**
 * @param {import("express").Request}  req
 * @param {import("express").Response} res
 * @param {import("express").NextFunction} next
 */
const authenticate = (req, _res, next) => {
  try {
    const authHeader = req.headers["authorization"];

    if (!authHeader?.startsWith("Bearer ")) {
      return next(new UnauthorizedError("Token de autenticação ausente."));
    }

    const token = authHeader.slice(7); // remove o prefixo "Bearer "
    req.user = jwtLib.verifyAccess(token);

    next();
  } catch (err) {
    next(err);
  }
};

module.exports = authenticate;

/**
 * src/middlewares/authorize.js
 *
 * Fábrica de middleware para controle de acesso baseado em roles (RBAC).
 * Deve ser usado após o middleware authenticate.
 *
 * Correção BUG-04: erros síncronos passados via next(err).
 *
 * OWASP API5 — controle de acesso em nível de função.
 *
 * @param {...string} roles  Roles permitidas (ex: "ADMIN", "USER")
 * @returns {import("express").RequestHandler}
 *
 * @example
 * router.get("/admin", authenticate, authorize("ADMIN"), handler);
 */

const { ForbiddenError } = require("../errors/AppError");

const authorize = (...roles) => (req, _res, next) => {
  try {
    if (!req.user || !roles.includes(req.user.role)) {
      return next(new ForbiddenError());
    }
    next();
  } catch (err) {
    next(err);
  }
};

module.exports = authorize;

/**
 * src/middlewares/errorHandler.js
 *
 * Handler global de erros — último middleware registrado no app.js.
 * Garante respostas controladas sem vazar stack traces ou internals em produção.
 *
 * OWASP API7 — security misconfiguration / information disclosure.
 */

const config = require("../config");
const { AppError, ValidationError } = require("../errors/AppError");

/**
 * @param {Error} err
 * @param {import("express").Request} req
 * @param {import("express").Response} res
 * @param {import("express").NextFunction} _next  Obrigatório ter 4 parâmetros para o Express reconhecer como error handler
 */
const errorHandler = (err, req, res, _next) => {
  // Log interno completo — stack trace, causa, metadados do Prisma, etc.
  console.error(
    `[ERROR] ${req.method} ${req.url} user=${req.user?.id ?? "-"}`,
    err
  );

  // ── Erros de negócio conhecidos ────────────────────────────────────────────
  if (err instanceof AppError) {
    const body = { error: err.message, code: err.code };

    if (err instanceof ValidationError && err.details?.length) {
      body.details = err.details;
    }

    return res.status(err.statusCode).json(body);
  }

  // ── Erros do Prisma ────────────────────────────────────────────────────────

  // P2002 — violação de constraint unique
  if (err.code === "P2002") {
    return res.status(409).json({ error: "Dado duplicado.", code: "CONFLICT" });
  }

  // P2025 — registro não encontrado em update/delete
  if (err.code === "P2025") {
    return res.status(404).json({ error: "Registro não encontrado.", code: "NOT_FOUND" });
  }

  // ── Erros inesperados ──────────────────────────────────────────────────────
  // Em produção: nunca expor stack trace ou mensagem interna.
  res.status(500).json({
    error: "Erro interno do servidor.",
    code:  "INTERNAL_ERROR",
    ...(config.app.isDev ? { detail: err.message } : {}),
  });
};

module.exports = errorHandler;

/**
 * src/middlewares/rateLimiter.js
 *
 * Proteção contra DoS e força bruta via rate limiting por camada.
 * Configurações centralizadas no config/index.js (MAN-01).
 *
 * OWASP API4 — consumo irrestrito de recursos.
 *
 * Nota ESC-01: o store padrão (in-memory) não é compartilhado entre múltiplos
 * processos/instâncias. Para escalar horizontalmente, substitua por um store
 * Redis usando o pacote `rate-limit-redis`:
 *
 *   const RedisStore = require("rate-limit-redis");
 *   store: new RedisStore({ sendCommand: (...args) => redis.sendCommand(args) })
 */

const rateLimit = require("express-rate-limit");
const config    = require("../config");

/**
 * Gera a chave de identificação para o rate limiter.
 * Usa o ID do usuário autenticado quando disponível; caso contrário, o IP.
 * Isso evita penalizar todos os usuários por trás do mesmo NAT/proxy.
 *
 * @param {import("express").Request} req
 * @returns {string}
 */
const keyGenerator = (req) =>
  req.user ? `user:${req.user.id}` : `ip:${req.ip}`;

/** Limiter global: 100 requisições por 15 minutos. */
const apiLimiter = rateLimit({
  windowMs:        config.rateLimit.global.windowMs,
  max:             config.rateLimit.global.max,
  standardHeaders: "draft-7",
  legacyHeaders:   false,
  keyGenerator,
  message: {
    error: "Muitas requisições. Tente novamente em alguns minutos.",
    code:  "RATE_LIMITED",
  },
});

/**
 * Limiter de autenticação: 10 tentativas por 15 minutos por IP.
 * Conta apenas requisições com falha (skipSuccessfulRequests: true).
 */
const authLimiter = rateLimit({
  windowMs:               config.rateLimit.auth.windowMs,
  max:                    config.rateLimit.auth.max,
  standardHeaders:        "draft-7",
  legacyHeaders:          false,
  keyGenerator:           (req) => `ip:${req.ip}`,
  skipSuccessfulRequests: true,
  message: {
    error: "Muitas tentativas de autenticação. Aguarde 15 minutos.",
    code:  "RATE_LIMITED",
  },
});

/** Limiter de escrita: 20 operações por minuto. */
const writeLimiter = rateLimit({
  windowMs:        config.rateLimit.write.windowMs,
  max:             config.rateLimit.write.max,
  standardHeaders: "draft-7",
  legacyHeaders:   false,
  keyGenerator,
  message: {
    error: "Limite de operações de escrita atingido. Tente novamente em breve.",
    code:  "RATE_LIMITED",
  },
});

module.exports = { apiLimiter, authLimiter, writeLimiter };

/**
 * src/middlewares/requestLogger.js
 *
 * Log de cada requisição: método, path, status e latência.
 * Nunca registra o body (pode conter senhas ou PII).
 *
 * Correção MAN-04: o timestamp é capturado no início da requisição,
 * não no evento "finish" (que pode ser alguns ms posterior).
 *
 * OWASP API9 — logging e monitoramento adequados.
 */

const requestLogger = (req, res, next) => {
  const startMs        = Date.now();
  const startTimestamp = new Date().toISOString(); // capturado no início

  res.on("finish", () => {
    const duration = Date.now() - startMs;
    const status   = res.statusCode;
    const level    = status >= 500 ? "ERROR" : status >= 400 ? "WARN" : "INFO";
    const userId   = req.user?.id ?? "-";

    console.log(
      `[${level}] ${startTimestamp} ${req.method} ${req.originalUrl}` +
      ` → ${status} (${duration}ms) user=${userId} ip=${req.ip}`
    );
  });

  next();
};

module.exports = requestLogger;

/**
 * src/repositories/auditRepository.js
 *
 * Acesso ao banco para registros de auditoria.
 * Falhas de auditoria nunca devem derrubar a operação principal,
 * mas o erro completo é logado para visibilidade (OWASP API9).
 *
 * Correção ORG-04: preserva stack trace no log de falha.
 * Correção MAN-02: usa constantes de AuditAction (importadas pelo caller).
 *
 * @typedef {Object} AuditEntry
 * @property {number|null}  [userId]
 * @property {string}       action
 * @property {number|null}  [targetId]
 * @property {string|null}  [targetType]
 * @property {object|null}  [meta]
 * @property {string|null}  [ip]
 */

const prisma = require("../lib/prisma");

/**
 * Registra uma entrada de auditoria de forma não-bloqueante.
 * Nunca lança exceção — absorve falhas com log completo.
 * @param {AuditEntry} entry
 * @returns {Promise<void>}
 */
const log = async (entry) => {
  try {
    await prisma.auditLog.create({ data: entry });
  } catch (err) {
    // Loga stack trace completo para depuração, sem propagar o erro
    console.error("[AUDIT] Falha ao registrar entrada de auditoria:", err);
  }
};

module.exports = { log };

/**
 * src/repositories/refreshTokenRepository.js
 *
 * Acesso ao banco para refresh tokens.
 * Tokens armazenados como hash SHA-256 — nunca o valor bruto (OWASP API2).
 *
 * Correções aplicadas:
 *   SEC-02 — revoke agora retorna contagem e o caller pode checar o resultado
 *   SEC-03 — findValid usa select explícito em vez de include, evitando
 *             retornar passwordHash do usuário na memória do service
 */

const prisma = require("../lib/prisma");
const crypto = require("crypto");

/**
 * Gera o hash SHA-256 de um token.
 * @param {string} token
 * @returns {string}
 */
const hashToken = (token) =>
  crypto.createHash("sha256").update(token).digest("hex");

/**
 * Campos do usuário retornados junto ao refresh token.
 * passwordHash explicitamente excluído (SEC-03).
 */
const USER_SELECT = {
  id:       true,
  email:    true,
  role:     true,
  isActive: true,
  name:     true,
};

/**
 * Cria um novo registro de refresh token.
 * @param {number}   userId
 * @param {string}   token      Valor bruto (será hasheado aqui)
 * @param {Date}     expiresAt
 */
const create = (userId, token, expiresAt) =>
  prisma.refreshToken.create({
    data: { userId, tokenHash: hashToken(token), expiresAt },
  });

/**
 * Busca um refresh token válido (não revogado e não expirado).
 * Retorna o registro junto ao usuário (sem passwordHash).
 * @param {string} token  Valor bruto do token
 * @returns {Promise<{ id: string, userId: number, user: object } | null>}
 */
const findValid = (token) =>
  prisma.refreshToken.findFirst({
    where: {
      tokenHash: hashToken(token),
      revokedAt: null,
      expiresAt: { gt: new Date() },
    },
    select: {
      id:        true,
      userId:    true,
      expiresAt: true,
      user:      { select: USER_SELECT },
    },
  });

/**
 * Revoga um token específico pelo seu valor bruto.
 * Retorna a contagem de registros afetados.
 * @param {string} token
 * @returns {Promise<number>}
 */
const revoke = async (token) => {
  const result = await prisma.refreshToken.updateMany({
    where: { tokenHash: hashToken(token), revokedAt: null },
    data:  { revokedAt: new Date() },
  });
  return result.count;
};

/**
 * Revoga todos os refresh tokens ativos de um usuário.
 * Usado em logout-all e em resposta a detecção de reuso.
 * @param {number} userId
 * @returns {Promise<number>}
 */
const revokeAllForUser = async (userId) => {
  const result = await prisma.refreshToken.updateMany({
    where: { userId, revokedAt: null },
    data:  { revokedAt: new Date() },
  });
  return result.count;
};

/**
 * Remove tokens expirados do banco.
 * Deve ser chamado periodicamente para evitar crescimento indefinido da tabela.
 * @returns {Promise<number>} Quantidade de registros removidos
 */
const deleteExpired = async () => {
  const result = await prisma.refreshToken.deleteMany({
    where: { expiresAt: { lt: new Date() } },
  });
  return result.count;
};

module.exports = { create, findValid, revoke, revokeAllForUser, deleteExpired };

/**
 * src/repositories/userRepository.js
 *
 * Acesso ao banco para a entidade User.
 * Toda interação com o Prisma fica aqui — services não importam o PrismaClient.
 *
 * Campos retornados nunca incluem passwordHash (select explícito em PUBLIC_FIELDS).
 * Versões "WithPassword" existem apenas para uso interno de autenticação (OWASP API3).
 *
 * @typedef {Object} PublicUser
 * @property {number}  id
 * @property {string}  name
 * @property {string}  email
 * @property {string}  role
 * @property {boolean} isActive
 * @property {Date}    createdAt
 * @property {Date}    updatedAt
 */

const prisma = require("../lib/prisma");

/** Projeção pública: exclui passwordHash de todas as respostas para clientes. */
const PUBLIC_FIELDS = {
  id:        true,
  name:      true,
  email:     true,
  role:      true,
  isActive:  true,
  createdAt: true,
  updatedAt: true,
};

/**
 * Lista usuários ativos com paginação.
 * @param {{ page?: number, limit?: number }} options
 * @returns {Promise<{ users: PublicUser[], total: number, page: number, limit: number }>}
 */
const findAll = async ({ page = 1, limit = 20 } = {}) => {
  const skip = (page - 1) * limit;

  const [users, total] = await prisma.$transaction([
    prisma.user.findMany({
      where:   { isActive: true },
      select:  PUBLIC_FIELDS,
      skip,
      take:    limit,
      orderBy: { createdAt: "desc" },
    }),
    prisma.user.count({ where: { isActive: true } }),
  ]);

  return { users, total, page, limit };
};

/**
 * Busca usuário por ID (sem passwordHash).
 * @param {number} id
 * @returns {Promise<PublicUser | null>}
 */
const findById = (id) =>
  prisma.user.findUnique({ where: { id }, select: PUBLIC_FIELDS });

/**
 * Busca usuário por ID incluindo passwordHash.
 * Uso exclusivo da camada de autenticação.
 * @param {number} id
 * @returns {Promise<object | null>}
 */
const findByIdWithPassword = (id) =>
  prisma.user.findUnique({ where: { id } });

/**
 * Busca usuário por e-mail (sem passwordHash).
 * @param {string} email
 * @returns {Promise<PublicUser | null>}
 */
const findByEmail = (email) =>
  prisma.user.findUnique({ where: { email }, select: PUBLIC_FIELDS });

/**
 * Busca usuário por e-mail incluindo passwordHash.
 * Uso exclusivo da camada de autenticação.
 * @param {string} email
 * @returns {Promise<object | null>}
 */
const findByEmailWithPassword = (email) =>
  prisma.user.findUnique({ where: { email } });

/**
 * Cria um novo usuário.
 * @param {{ name: string, email: string, passwordHash: string, role?: string }} data
 * @returns {Promise<PublicUser>}
 */
const create = (data) =>
  prisma.user.create({ data, select: PUBLIC_FIELDS });

/**
 * Atualiza campos de um usuário pelo ID.
 * @param {number} id
 * @param {{ name?: string, email?: string, role?: string }} data
 * @returns {Promise<PublicUser>}
 */
const update = (id, data) =>
  prisma.user.update({ where: { id }, data, select: PUBLIC_FIELDS });

/**
 * Soft-delete: marca o usuário como inativo sem remover fisicamente.
 * Preserva integridade referencial nos logs de auditoria.
 * @param {number} id
 * @returns {Promise<PublicUser>}
 */
const softDelete = (id) =>
  prisma.user.update({
    where:  { id },
    data:   { isActive: false },
    select: PUBLIC_FIELDS,
  });

module.exports = {
  findAll,
  findById,
  findByIdWithPassword,
  findByEmail,
  findByEmailWithPassword,
  create,
  update,
  softDelete,
};

