/**
 * src/services/authService.js
 *
 * Lógica de negócio para autenticação.
 * Orquestra login, rotação de refresh token, logout e auditoria.
 *
 * Correções aplicadas:
 *   BUG-02 — timingSafeCompare usa hash válido pré-computado, sem exceção
 *   SEC-04 — refresh verifica user.isActive antes de emitir novos tokens
 *   MAN-02 — usa constantes AuditAction
 */

const userRepo         = require("../repositories/userRepository");
const refreshTokenRepo = require("../repositories/refreshTokenRepository");
const auditRepo        = require("../repositories/auditRepository");
const password         = require("../lib/password");
const jwt              = require("../lib/jwt");
const config           = require("../config");
const { AuditAction }  = require("../constants/auditActions");
const { UnauthorizedError } = require("../errors/AppError");

/**
 * Autentica o usuário com e-mail e senha.
 * Timing-safe: executa bcrypt mesmo quando o usuário não existe (OWASP API2).
 *
 * @param {string} email
 * @param {string} plainPassword
 * @param {string} ip
 * @returns {Promise<{ accessToken: string, refreshToken: string, user: object }>}
 */
const login = async (email, plainPassword, ip) => {
  const user = await userRepo.findByEmailWithPassword(email);

  // Sempre executa bcrypt — evita timing attack / user enumeration
  const isValid = user
    ? await password.verify(plainPassword, user.passwordHash)
    : await password.timingSafeCompare(plainPassword);

  if (!user || !isValid || !user.isActive) {
    await auditRepo.log({ action: AuditAction.LOGIN_FAILED, meta: { email }, ip });
    throw new UnauthorizedError("Credenciais inválidas.");
  }

  const { passwordHash: _removed, ...safeUser } = user;

  const accessToken  = jwt.signAccess({ id: user.id, email: user.email, role: user.role });
  const refreshToken = jwt.signRefresh({ id: user.id });
  const expiresAt    = new Date(Date.now() + config.jwt.refreshTtlMs);

  await refreshTokenRepo.create(user.id, refreshToken, expiresAt);
  await auditRepo.log({ userId: user.id, action: AuditAction.LOGIN_SUCCESS, ip });

  return { accessToken, refreshToken, user: safeUser };
};

/**
 * Rotação de refresh token: invalida o anterior e emite um novo par.
 * Reutilização de token revogado aciona revogação total (breach response).
 * Verifica isActive para bloquear usuários desativados (SEC-04).
 *
 * @param {string} oldRefreshToken
 * @param {string} ip
 * @returns {Promise<{ accessToken: string, refreshToken: string }>}
 */
const refresh = async (oldRefreshToken, ip) => {
  // Verifica assinatura e expiração JWT antes de consultar o banco
  const decoded = jwt.verifyRefresh(oldRefreshToken);
  const stored  = await refreshTokenRepo.findValid(oldRefreshToken);

  if (!stored || stored.userId !== decoded.id) {
    // Possível reutilização de token revogado — revoga tudo do usuário
    if (decoded?.id) {
      await refreshTokenRepo.revokeAllForUser(decoded.id);
    }
    await auditRepo.log({
      action: AuditAction.REFRESH_TOKEN_REUSE,
      meta:   { userId: decoded?.id },
      ip,
    });
    throw new UnauthorizedError("Refresh token inválido.");
  }

  // Garante que o usuário continua ativo (SEC-04)
  if (!stored.user.isActive) {
    await refreshTokenRepo.revokeAllForUser(stored.userId);
    throw new UnauthorizedError("Conta desativada.");
  }

  // Revoga o token antigo (rotação obrigatória)
  await refreshTokenRepo.revoke(oldRefreshToken);

  const { user }     = stored;
  const accessToken  = jwt.signAccess({ id: user.id, email: user.email, role: user.role });
  const refreshToken = jwt.signRefresh({ id: user.id });
  const expiresAt    = new Date(Date.now() + config.jwt.refreshTtlMs);

  await refreshTokenRepo.create(user.id, refreshToken, expiresAt);

  return { accessToken, refreshToken };
};

/**
 * Revoga o refresh token corrente (logout do dispositivo atual).
 * @param {string} refreshToken
 * @param {number} userId
 * @param {string} ip
 */
const logout = async (refreshToken, userId, ip) => {
  await refreshTokenRepo.revoke(refreshToken);
  await auditRepo.log({ userId, action: AuditAction.LOGOUT, ip });
};

/**
 * Revoga todos os refresh tokens do usuário (logout de todos os dispositivos).
 * @param {number} userId
 * @param {string} ip
 */
const logoutAll = async (userId, ip) => {
  await refreshTokenRepo.revokeAllForUser(userId);
  await auditRepo.log({ userId, action: AuditAction.LOGOUT_ALL, ip });
};

module.exports = { login, refresh, logout, logoutAll };

/**
 * src/services/userService.js
 *
 * Lógica de negócio para gerenciamento de usuários.
 * Aplica regras de autorização (BOLA e RBAC) antes de qualquer operação.
 *
 * Correções aplicadas:
 *   BUG-01 — removido lookup duplo / dead code em createUser
 *   MAN-02 — usa constantes AuditAction
 *
 * @typedef {{ requesterId: number, requesterRole: string }} RequesterContext
 */

const userRepo   = require("../repositories/userRepository");
const auditRepo  = require("../repositories/auditRepository");
const password   = require("../lib/password");
const { AuditAction } = require("../constants/auditActions");
const {
  NotFoundError,
  ConflictError,
  ForbiddenError,
} = require("../errors/AppError");

/**
 * Garante que o usuário existe e está ativo.
 * Lança NotFoundError caso contrário.
 * @param {number} id
 */
const assertExists = async (id) => {
  const user = await userRepo.findById(id);
  if (!user) throw new NotFoundError("Usuário");
  return user;
};

/**
 * Lista usuários ativos com paginação.
 * Restrito a ADMINs (OWASP API5).
 *
 * @param {{ page: number, limit: number } & RequesterContext} params
 */
const listUsers = async ({ page, limit, requesterId, requesterRole }) => {
  if (requesterRole !== "ADMIN") throw new ForbiddenError();

  await auditRepo.log({ userId: requesterId, action: AuditAction.USER_LIST });

  return userRepo.findAll({ page, limit });
};

/**
 * Busca usuário por ID.
 * USERs só podem ver seu próprio perfil; ADMINs veem qualquer um (OWASP API1).
 *
 * @param {number} targetId
 * @param {RequesterContext} ctx
 */
const getUserById = async (targetId, { requesterId, requesterRole }) => {
  // BOLA check — verifica ANTES de consultar o banco
  if (requesterRole !== "ADMIN" && requesterId !== targetId) {
    throw new ForbiddenError();
  }

  const user = await userRepo.findById(targetId);
  if (!user) throw new NotFoundError("Usuário");

  return user;
};

/**
 * Cria um novo usuário.
 * Apenas ADMINs podem definir roles diferentes de USER (OWASP API5).
 *
 * @param {{ name: string, email: string, password: string, role?: string }} data
 * @param {RequesterContext} ctx
 */
const createUser = async (data, { requesterId, requesterRole }) => {
  // Verifica unicidade do e-mail (único lookup necessário — BUG-01 corrigido)
  const duplicate = await userRepo.findByEmail(data.email);
  if (duplicate) throw new ConflictError("E-mail já está em uso.");

  // Impede escalonamento de privilégio
  if (data.role && data.role !== "USER" && requesterRole !== "ADMIN") {
    throw new ForbiddenError("Somente administradores podem definir roles.");
  }

  const passwordHash = await password.hash(data.password);
  const assignedRole = requesterRole === "ADMIN" ? (data.role ?? "USER") : "USER";

  const user = await userRepo.create({
    name:  data.name,
    email: data.email,
    passwordHash,
    role:  assignedRole,
  });

  await auditRepo.log({
    userId:     requesterId,
    action:     AuditAction.USER_CREATED,
    targetId:   user.id,
    targetType: "User",
  });

  return user;
};

/**
 * Atualiza dados de um usuário.
 * USERs só atualizam a si mesmos; somente ADMINs alteram roles (OWASP API1, API5).
 *
 * @param {number} targetId
 * @param {{ name?: string, email?: string, role?: string }} data
 * @param {RequesterContext} ctx
 */
const updateUser = async (targetId, data, { requesterId, requesterRole }) => {
  await assertExists(targetId);

  // BOLA check
  if (requesterRole !== "ADMIN" && requesterId !== targetId) {
    throw new ForbiddenError();
  }

  // Impede escalonamento de privilégio
  if (data.role !== undefined && requesterRole !== "ADMIN") {
    throw new ForbiddenError("Somente administradores podem alterar roles.");
  }

  // Verifica unicidade do novo e-mail
  if (data.email) {
    const conflict = await userRepo.findByEmail(data.email);
    if (conflict && conflict.id !== targetId) {
      throw new ConflictError("E-mail já está em uso por outro usuário.");
    }
  }

  const updated = await userRepo.update(targetId, data);

  await auditRepo.log({
    userId:     requesterId,
    action:     AuditAction.USER_UPDATED,
    targetId,
    targetType: "User",
    meta:       { fields: Object.keys(data) },
  });

  return updated;
};

/**
 * Desativa (soft-delete) um usuário.
 * USERs só removem a si mesmos; ADMINs não podem se auto-remover (OWASP API1).
 *
 * @param {number} targetId
 * @param {RequesterContext} ctx
 */
const deleteUser = async (targetId, { requesterId, requesterRole }) => {
  await assertExists(targetId);

  if (requesterRole !== "ADMIN" && requesterId !== targetId) {
    throw new ForbiddenError();
  }

  if (requesterRole === "ADMIN" && requesterId === targetId) {
    throw new ForbiddenError("Administrador não pode desativar a própria conta.");
  }

  await userRepo.softDelete(targetId);

  await auditRepo.log({
    userId:     requesterId,
    action:     AuditAction.USER_DELETED,
    targetId,
    targetType: "User",
  });
};

module.exports = { listUsers, getUserById, createUser, updateUser, deleteUser };

/**
 * src/validators/authValidator.js
 *
 * Schema Zod para a rota de login.
 * Validação mínima intencional: mensagens de erro de login são genéricas
 * para não revelar se o e-mail existe (OWASP API2).
 */

const { z } = require("zod");

const loginSchema = z.object({
  email: z
    .string({ required_error: "'email' é obrigatório." })
    .email("Credenciais inválidas."),

  password: z
    .string({ required_error: "'password' é obrigatório." })
    .min(1, "Credenciais inválidas."),
});

module.exports = { loginSchema };
